def choose_move(observation):
    def _num(v, d=0):
        return v if isinstance(v, (int, float)) else d

    def _pos(v):
        if isinstance(v, (list, tuple)) and len(v) >= 2:
            return [_num(v[0], 0), _num(v[1], 0)]
        return [0, 0]

    def _clamp_step(a, b):
        return 0 if a == b else (1 if b > a else -1)

    def _best_target(points, sx, sy, prefer_far=False):
        best = None
        best_score = None
        for p in points or []:
            pp = _pos(p)
            score = abs(pp[0] - sx) + abs(pp[1] - sy)
            if prefer_far:
                score = -score
            if best is None or score < best_score:
                best = pp
                best_score = score
        return best

    env = observation.get("environment_name", "resource_collection")
    self_pos = _pos(observation.get("self_position", [0, 0]))
    sx, sy = self_pos[0], self_pos[1]
    opp_pos = _pos(observation.get("opponent_position", [sx, sy]))
    ox, oy = opp_pos[0], opp_pos[1]

    role = observation.get("self_role", "")

    if env == "pursuit_evasion":
        if role == "pursuer":
            return [_clamp_step(sx, ox), _clamp_step(sy, oy)]
        gw = _num(observation.get("grid_width", 0), 0)
        gh = _num(observation.get("grid_height", 0), 0)
        corners = [[0, 0], [0, gh - 1], [gw - 1, 0], [gw - 1, gh - 1]]
        target = _best_target(corners, ox, oy, prefer_far=True) or [0, 0]
        return [_clamp_step(sx, target[0]), _clamp_step(sy, target[1])]

    if env == "territory_control":
        targets = []
        for key in ("unclaimed_cells", "opponent_territory", "enemy_territory", "frontier_cells", "targets"):
            vals = observation.get(key)
            if vals:
                targets.extend(vals)
        if not targets:
            gw = _num(observation.get("grid_width", 0), 0)
            gh = _num(observation.get("grid_height", 0), 0)
            if gw > 0 and gh > 0:
                targets = [[gw // 2, gh // 2]]
            else:
                targets = [[ox, oy]]
        best = _best_target(targets, sx, sy) or [sx, sy]
        return [_clamp_step(sx, best[0]), _clamp_step(sy, best[1])]

    resources = observation.get("resources") or observation.get("resource_positions") or []
    if resources:
        best = _best_target(resources, sx, sy) or [sx, sy]
        return [_clamp_step(sx, best[0]), _clamp_step(sy, best[1])]

    # Generic fallback: move toward opponent if closer, otherwise toward board center if known.
    gw = _num(observation.get("grid_width", 0), 0)
    gh = _num(observation.get("grid_height", 0), 0)
    if gw > 0 and gh > 0:
        cx, cy = gw // 2, gh // 2
        if abs(ox - sx) + abs(oy - sy) > abs(cx - sx) + abs(cy - sy):
            return [_clamp_step(sx, cx), _clamp_step(sy, cy)]
    return [_clamp_step(sx, ox), _clamp_step(sy, oy)]

